begin;
-- Clearly labelled four-person synthetic fixture only. All writes roll back.
do $test$
declare
 trip uuid:='791e21bb-b93e-470b-a22e-5dbad90b8863';host uuid:='8d80db6b-2cf2-4dc5-b0b5-16a7fa82f2b5';m1 uuid:='18d569d2-5f3e-474d-9688-e5cf249e7527';m2 uuid:='c52fd525-4ea7-4b73-8e32-1cd1a7320ebc';m3 uuid:='a028d463-9554-4d2c-bc10-95dc6e3a1de6';
 plan uuid:='93d9c27c-b9be-4799-8d26-7cbaf0e41eea';b jsonb;s jsonb;payload jsonb;bad jsonb;denied boolean;checked int:=0;eid uuid:=gen_random_uuid();refundid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();stale text;detail_text text;
begin
 if not exists(select 1 from public.planzo_trips where id=trip and name like 'TEST %Phase 3 booking QA 1fcb41f1' and created_by=host) then raise exception 'Expected labelled fixture missing';end if;
 delete from planzo_private.flow_payment_events where trip_id=trip;
 delete from planzo_private.flow_payment_settlements where trip_id=trip;
 delete from planzo_private.flow_payment_expenses where trip_id=trip;
 delete from planzo_private.flow_payment_booking_shares where trip_id=trip;
 delete from planzo_private.flow_booking_events where trip_id=trip;
 perform set_config('request.jwt.claim.sub',host::text,true);
 if has_function_privilege('anon','public.planzo_payments(text,jsonb)','EXECUTE') or has_function_privilege('authenticated','planzo_private.payments_state(uuid)','EXECUTE') or has_table_privilege('authenticated','planzo_private.flow_payment_expenses','SELECT') then raise exception 'privileges regression';end if;checked:=checked+1;
 b:=jsonb_build_object('trip_id',trip,'plan_id',plan,'step_id','step_13','expected_revision',0,'request_id',gen_random_uuid(),'status','booked','provider_name','TEST hotel','amount_paise',10001,'booked_by',m1,'reference','TEST','notes','TEST rollback only');
 perform public.planzo_booking_tracker('save',b);
 s:=public.planzo_payments('get',jsonb_build_object('trip_id',trip));
 if jsonb_array_length(s->'entries')<>0 or exists(select 1 from jsonb_array_elements(s->'balances')x where (x->>'balance_paise')::bigint<>0) then raise exception 'Booking still creates an expense';end if;checked:=checked+1;
 perform public.planzo_booking_tracker('save',b);
 if exists(select 1 from planzo_private.flow_payment_booking_shares where trip_id=trip) or exists(select 1 from planzo_private.flow_payment_events where trip_id=trip) then raise exception 'Booking still writes payment data';end if;checked:=checked+1;
 payload:=jsonb_build_object('trip_id',trip,'id',eid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','title','TEST dinner','amount_paise',10001,'payer_id',host,'kind','expense','split_mode','equal','shares',planzo_private.payment_equal_shares(10001,array[host,m1,m2,m3]),'paid_on',current_date,'notes','TEST');
 stale:=s->>'stamp';s:=public.planzo_payments('save_expense',payload);
 if jsonb_array_length(s->'entries')<>1 or(select sum((x->>'balance_paise')::bigint) from jsonb_array_elements(s->'balances')x)<>0 then raise exception 'Independent equal expense';end if;checked:=checked+1;
 perform public.planzo_payments('save_expense',payload);
 if(select count(*) from planzo_private.flow_payment_expenses where trip_id=trip)<>1 then raise exception 'Expense duplicated';end if;checked:=checked+1;
 denied:=false;begin perform public.planzo_payments('save_expense',payload||jsonb_build_object('request_id',gen_random_uuid(),'id',gen_random_uuid(),'expected_stamp',stale));exception when sqlstate 'PGRST' then get stacked diagnostics detail_text=pg_exception_detail;denied:=(sqlerrm::jsonb->>'code'='40001' and detail_text::jsonb->>'status'='409');end;
 if not denied then raise exception 'Stale ledger accepted';end if;checked:=checked+1;
 perform public.planzo_booking_tracker('save',b||jsonb_build_object('expected_revision',1,'request_id',gen_random_uuid(),'amount_paise',50003));
 if planzo_private.payments_state(trip)->>'stamp'<>s->>'stamp' then raise exception 'Booking update changes independent ledger';end if;checked:=checked+1;
 update public.planzo_trip_members set included=false where trip_id=trip and user_id=m3;
 s:=public.planzo_payments('get',jsonb_build_object('trip_id',trip));
 if jsonb_array_length(s#>'{entries,0,shares}')<>4 then raise exception 'Dropout rewrote historical expense';end if;checked:=checked+1;
 update public.planzo_trip_members set included=true where trip_id=trip and user_id=m3;s:=public.planzo_payments('get',jsonb_build_object('trip_id',trip));
 for bad in select value from jsonb_array_elements('[{"amount_paise":-1},{"amount_paise":1.2},{"amount_paise":10000000001},{"payer_id":"00000000-0000-0000-0000-000000000001"},{"actor":"00000000-0000-0000-0000-000000000001"},{"kind":"other"},{"shares":[]},{"shares":[{"user_id":"00000000-0000-0000-0000-000000000001","amount_paise":10001}]},{"shares":[{"user_id":"18d569d2-5f3e-474d-9688-e5cf249e7527","amount_paise":10000}]}]'::jsonb) loop
  denied:=false;begin perform public.planzo_payments('save_expense',payload||jsonb_build_object('id',gen_random_uuid(),'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp')||bad);exception when others then denied:=true;end;
  if not denied then raise exception 'Bad expense accepted %',bad;end if;checked:=checked+1;
 end loop;
 -- Simplify a known two-person debt: host pays 100.01 entirely for m1.
 payload:=payload||jsonb_build_object('request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','split_mode','exact','shares',jsonb_build_array(jsonb_build_object('user_id',m1,'amount_paise',10001)));
 s:=public.planzo_payments('save_expense',payload);
 if(select x->>'balance_paise' from jsonb_array_elements(s->'balances')x where x->>'user_id'=host::text)<>'10001' then raise exception 'Custom split';end if;checked:=checked+1;
 s:=public.planzo_payments('save_expense',payload||jsonb_build_object('id',refundid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','kind','refund','amount_paise',501,'shares',jsonb_build_array(jsonb_build_object('user_id',m1,'amount_paise',501))));
 if(select x->>'balance_paise' from jsonb_array_elements(s->'balances')x where x->>'user_id'=host::text)<>'9500' then raise exception 'Refund';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',m1::text,true);
 payload:=jsonb_build_object('trip_id',trip,'id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','to_id',host,'amount_paise',2500,'method','Cash','paid_on',current_date,'notes','TEST only','acknowledged',true);
 s:=public.planzo_payments('record_settlement',payload);
 if(select x->>'balance_paise' from jsonb_array_elements(s->'balances')x where x->>'user_id'=host::text)<>'7000' or s#>>'{settlements,0,status}'<>'confirmed' then raise exception 'Payment does not apply immediately';end if;checked:=checked+1;
 perform public.planzo_payments('record_settlement',payload);
 if(select count(*) from planzo_private.flow_payment_settlements where trip_id=trip)<>1 then raise exception 'Payment duplicated';end if;checked:=checked+1;
 denied:=false;begin perform public.planzo_payments('record_settlement',payload||jsonb_build_object('amount_paise',2501));exception when others then denied:=true;end;
 if not denied then raise exception 'Altered idempotent payment accepted';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',m2::text,true);denied:=false;
 begin perform public.planzo_payments('cancel_settlement',jsonb_build_object('trip_id',trip,'id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp'));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Unrelated member removed settlement';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',host::text,true);
 s:=public.planzo_payments('cancel_settlement',jsonb_build_object('trip_id',trip,'id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp'));
 if(select x->>'balance_paise' from jsonb_array_elements(s->'balances')x where x->>'user_id'=host::text)<>'9500' then raise exception 'Recipient removal failed to restore balance';end if;checked:=checked+1;
 denied:=false;begin perform public.planzo_payments('confirm_settlement',jsonb_build_object('trip_id',trip,'id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','acknowledged',true));exception when others then denied:=true;end;
 if not denied then raise exception 'Receipt action remains';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',m1::text,true);sid:=gen_random_uuid();
 s:=public.planzo_payments('record_settlement',payload||jsonb_build_object('id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp','amount_paise',9500));
 if exists(select 1 from jsonb_array_elements(s->'balances')x where (x->>'balance_paise')::bigint<>0) then raise exception 'Full settlement';end if;checked:=checked+1;
 s:=public.planzo_payments('cancel_settlement',jsonb_build_object('trip_id',trip,'id',sid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp'));
 if(select x->>'balance_paise' from jsonb_array_elements(s->'balances')x where x->>'user_id'=host::text)<>'9500' then raise exception 'Sender removal failed';end if;checked:=checked+1;
 perform public.planzo_booking_tracker('save',b||jsonb_build_object('expected_revision',2,'request_id',gen_random_uuid(),'status','cancelled','amount_paise',null));
 if planzo_private.payments_state(trip)->>'stamp'<>s->>'stamp' then raise exception 'Cancelled booking changes ledger';end if;checked:=checked+1;
 update public.planzo_trip_members set included=false where trip_id=trip and user_id=m2;perform set_config('request.jwt.claim.sub',m2::text,true);denied:=false;
 begin perform public.planzo_payments('get',jsonb_build_object('trip_id',trip));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Excluded member access';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',m1::text,true);denied:=false;
 begin perform public.planzo_payments('get','{"trip_id":"0e3bd462-44b8-4b7b-8703-32858797c1c6"}');exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Cross-trip access';end if;checked:=checked+1;
 perform set_config('request.jwt.claim.sub',host::text,true);
 update public.planzo_trips set stage='archived',removal_kind='archived',removed_at=now() where id=trip;
 s:=public.planzo_payments('get',jsonb_build_object('trip_id',trip));if(s->>'editable')::boolean then raise exception 'Archive editable';end if;checked:=checked+1;
 denied:=false;begin perform public.planzo_payments('void_expense',jsonb_build_object('trip_id',trip,'id',eid,'request_id',gen_random_uuid(),'expected_stamp',s->>'stamp'));exception when others then denied:=true;end;
 if not denied then raise exception 'Archive write';end if;checked:=checked+1;
 perform set_config('planzo.independent_payment_checks',checked::text,true);
end $test$;
select current_setting('planzo.independent_payment_checks')::integer checks_passed;

rollback;
